+/** Theoretical vs actual ingredient use per item between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    const dish = getDish(store, s.dishId);
+    const recipe = getRecipe(store, dish.recipeId);
+    for (const n of scaled(recipe, s.qty)) {
+      theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+
+  const itemIds = new Set([...theoretical.keys(), ...actual.keys()]);
+  const lines = [];
+  for (const itemId of [...itemIds].sort((a, b) => a - b)) {
+    const theo = Math.round((theoretical.get(itemId) ?? 0) * 1000) / 1000;
+    const act = Math.round((actual.get(itemId) ?? 0) * 1000) / 1000;
+    if (theo <= 0 && act <= 0) continue;
+    const item = getItem(store, itemId);
+    const diff = Math.round((act - theo) * 1000) / 1000;
+    lines.push({ itemId, name: item.name, theoretical: theo, actual: act, diff });
+  }
+  return lines;
+}
