+++ b/src/io/sales-import.js
@@ -0,0 +1,71 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Already-imported tickets are skipped. All rows and stock are checked first;
+// one bad row or shortfall and nothing is imported.
+import { isInstant } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports sales; returns { tickets, dishes } counts or throws bad_request naming the row. */
+export function importSales(store, text) {
+  const rows = parseCsvObjects(text);
+  const existingTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+
+  const parsed = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    for (const k of HEADER) if (!(k in r)) throw new AppError("bad_request", { reason: `${where}: missing column ${k}` });
+    const ticket = r.ticket;
+    if (!ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const soldAt = new Date(r.soldAt).toISOString();
+    const dishId = Number(r.dishId);
+    if (!Number.isInteger(dishId) || dishId < 1) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish ${dishId}` });
+    const qty = Number(r.qty);
+    if (!Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    const recipe = getRecipe(store, dish.recipeId);
+    return { where, ticket, soldAt, dishId, qty, recipe };
+  });
+
+  const toImport = parsed.filter((r) => !existingTickets.has(r.ticket));
+
+  // Simulate stock consumption across all rows to import before mutating the store.
+  const remaining = new Map();
+  for (const r of toImport) {
+    for (const n of scaled(r.recipe, r.qty)) {
+      if (n.qty <= 0) continue;
+      const item = getItem(store, n.itemId);
+      const available = remaining.has(n.itemId) ? remaining.get(n.itemId) : onHand(store, n.itemId);
+      if (available < n.qty) {
+        throw new AppError("bad_request", { reason: `${r.where}: not enough ${item.name} (${available} ${item.unit} left)` });
+      }
+      remaining.set(n.itemId, Math.round((available - n.qty) * 1000) / 1000);
+    }
+  }
+
+  store.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  for (const r of toImport) {
+    for (const n of scaled(r.recipe, r.qty)) {
+      if (n.qty <= 0) continue;
+      consume(store, n.itemId, n.qty, { at: r.soldAt, ref: `sale:${r.ticket}` });
+    }
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: r.ticket,
+      soldAt: r.soldAt,
+      dishId: r.dishId,
+      qty: r.qty,
+    });
+    tickets.add(r.ticket);
+    dishes += r.qty;
+  }
+
+  return { tickets: tickets.size, dishes };
+}
